CREATE OR REPLACE FUNCTION public.prevent_manual_broker_approval_transfer() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.user_id IS DISTINCT FROM OLD.user_id THEN RAISE EXCEPTION 'license_already_approved_for_another_account'; END IF; RETURN NEW; END $$;
CREATE TRIGGER prevent_manual_broker_approval_transfer BEFORE UPDATE ON public.admin_approved_broker_licenses FOR EACH ROW EXECUTE FUNCTION public.prevent_manual_broker_approval_transfer();
CREATE OR REPLACE FUNCTION public.register_as_broker(_display_name text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); lic text; nm text; ph text; em text; lead uuid; warning text; manual boolean; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(uid::text,0)); IF NOT public.publisher_sms_verified() THEN RAISE EXCEPTION 'broker_sms_verification_required'; END IF; SELECT p.broker_license_number INTO lic FROM public.profiles p WHERE p.id=uid; manual:=EXISTS(SELECT 1 FROM public.admin_approved_broker_licenses a WHERE a.user_id=uid AND a.license_number=lic); IF NOT manual THEN IF NOT public.partner_can_view_closing(uid) OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=uid AND role IN ('agent','lead_agent','managing_broker')) THEN IF NOT EXISTS(SELECT 1 FROM public.broker_upgrade_requests WHERE user_id=uid AND status='approved') THEN RAISE EXCEPTION 'broker_identity_approval_required'; END IF; END IF; SELECT license_number INTO lic FROM public.broker_license_verifications WHERE user_id=uid AND source_url='https://data.gov.il/dataset/d361f6a6-898c-4e4d-8a80-abc4e8643bf6' AND source_updated_at>now()-interval '7 days'; END IF; IF lic IS NULL OR NOT public.broker_license_approved_for(uid,lic) THEN RAISE EXCEPTION 'broker_license_registry_verification_required'; END IF; PERFORM public.ensure_profile_row(uid); UPDATE public.profiles SET broker_license_number=lic WHERE id=uid; INSERT INTO public.user_roles(user_id,role) VALUES(uid,'agent') ON CONFLICT(user_id,role) DO NOTHING; IF NOT manual THEN UPDATE public.profiles SET full_name=public.official_broker_name(uid,lic),locked_broker_name=public.official_broker_name(uid,lic) WHERE id=uid; END IF; SELECT full_name,phone,email INTO nm,ph,em FROM public.profiles WHERE id=uid; IF NULLIF(regexp_replace(COALESCE(ph,''),'\D','','g'),'') IS NOT NULL THEN BEGIN lead:=public.ensure_rita_crm_contact(nm,ph,em,'הרשמת מתווך לאפליקציה','app_registration',uid); EXCEPTION WHEN OTHERS THEN warning:=SQLERRM; END; ELSE warning:='registration_phone_missing'; END IF; RETURN jsonb_build_object('ok',true,'user_id',uid,'role','agent','lead_id',lead,'warning',warning); END $$;